import * as React from 'react';
import { cn } from '@/lib/utils';

export interface StreamingIndicatorProps {
  isStreaming: boolean;
  className?: string;
  text?: string;
}

/**
 * Animated three-dot streaming indicator. Announces the streaming state
 * to screen readers via role="status" / aria-live so assistive tech
 * users know generation is in progress.
 */
const StreamingIndicator = React.forwardRef<HTMLDivElement, StreamingIndicatorProps>(
  ({ isStreaming, className, text = 'Generating...', ...props }, ref) => {
    if (!isStreaming) {
      return null;
    }

    return (
      <div
        ref={ref}
        role="status"
        aria-live="polite"
        aria-label={text}
        className={cn('flex items-center gap-2 text-sm text-muted-foreground', className)}
        {...props}
      >
        <div className="flex gap-1" aria-hidden="true">
          {[0, 150, 300].map((delay) => (
            <span
              key={delay}
              className="w-2 h-2 bg-primary rounded-full animate-pulse motion-reduce:animate-none"
              style={{ animationDelay: `${delay}ms` }}
            />
          ))}
        </div>
        <span>{text}</span>
      </div>
    );
  }
);
StreamingIndicator.displayName = 'StreamingIndicator';

export { StreamingIndicator };

{
  "id": "streaming-indicator",
  "name": "StreamingIndicator",
  "tier": "atom",
  "description": "Shows that an AI response is currently streaming.",
  "designIntent": "Give users immediate feedback while generated content is arriving.",
  "props": [
    {
      "name": "isStreaming",
      "type": "boolean",
      "required": true,
      "description": "Whether the indicator is visible."
    },
    {
      "name": "text",
      "type": "string",
      "defaultValue": "Generating…",
      "required": false,
      "description": "Status text."
    }
  ],
  "examples": [
    {
      "title": "Generating state",
      "code": "<StreamingIndicator isStreaming={true} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Status text",
      "implementation": "The state includes human-readable text in addition to animation."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1",
  "sourceDir": "streaming",
  "exportName": "StreamingIndicator"
}
